from save_review import save
save(1311,{2:'激光炮在英文中也称 Laser Cannon，另有 Blazooga 的别称。这种武器威力强大，能击穿多数载具装甲，杀死强壮或重甲防护的敌人。但它充能慢、射速低，不适合用来普遍杀伤步兵。',7:'激光枪与激光炮的主要区别在于尺寸。普通卫队士兵可以轻松使用激光枪，激光炮却大得多，也重得多，通常需要固定安装或由武器组操作。星际战士凭借基因增强的力量和动力盔甲，则能轻松携带并抵肩发射。',11:'激光炮的可拆卸能量单元只能供射击一次。如果没有外接电源，就需要一名炮组成员负责更换。',13:'激光炮的技术已经得到充分完善，并非只是从古代标准建造模板（STC）中东拼西凑而来，因此十分可靠。许多帝国指挥官尤其青睐它：其他武器或许各有优势，但战场上最要紧的仍是可靠性。',15:'House Van Saar double-barreled Lascannon 凡·萨尔家族的双管激光炮',17:'激光炮威力大、可靠性高，常被安装于坦克，并以双联配置提高精度。许多坦克在侧炮座或车体上安装激光炮作为副武器，即使主炮塔损坏，仍可继续作战。激光炮在帝国卫队中十分常见，在更依赖热熔武器的星际战士中则相对较少。',34:'首要标准建造模板型——安装于部分帝国坦克，包括某些毒刃型号。',36:'风暴使者型——用于歼灭者型掠食者战车。',38:'太阳军型——KZ8.23 系列，在泰拉制造，曾于大远征和荷鲁斯之乱期间配发给阿斯塔特军团。',42:'重型激光炮——由帝国卫队的野战炮群使用。',44:'沃斯型——安装于女武神炮艇。',47:'激光撕裂炮——阿斯特赖俄斯超重型坦克使用。',49:'激光爪——安装于风暴鹰拦截者战机和反重力战车。',51:'巨型激光炮——安装于巨人王型阿卡斯托斯骑士。',53:'阿拉克纳斯重型激光炮——用于德雷都型无畏机甲。',55:'索莱克斯重型激光炮——用于圣杯型死灭级机兵。'},notes={7:'原译将lasgun与lascannon都译成激光炮，现恢复两者尺寸对比。',38:'Range在型号说明中暂按系列处理；原文没有距离单位，不将KZ8.23解释为射程数值。'},terms=[('Lascannon','激光炮'),('Blazooga','布拉佐加'),('Godhammer Pattern','神锤型'),('Hell Hammer Pattern','地狱之锤型'),('Primus Standard Template Construct Pattern','首要标准建造模板型'),('Stormbringer Pattern','风暴使者型'),('Magna Lascannon','巨型激光炮')])
save(1312,{2:'激光爪是风暴鹰拦截者战机和原铸反重力战车使用的重型激光武器。',6:'激光爪能迅速连续射出两道强力激光，足以干净利落地摧毁极厚重的装甲目标。与其他重型激光武器不同，它的射程较短，远距离上的杀伤力会大幅衰减。',8:'雷击型风暴速攻艇装有一种称为雷击激光爪的改型。'},terms=[('Las-Talon','激光爪'),('Thunderstrike Las-Talon','雷击激光爪')])
save(1313,{2:'火山炮是人类帝国最强大的地面激光武器之一，能以太瓦级功率射出炽白光束，伴随雷鸣般的炸响和巨大的后坐力。',5:'它射程极远，单次开火便能切断泰坦的肢体，或摧毁一台敌方战争机器。不过，拥有完整虚空盾的战犬级侦察泰坦仍可能承受一次直接命中。面对较小目标时，它的威力同样惊人：豪猪战车会被彻底抹去，只留一片焦痕；一扇百米高的厚重铁门也能被完全汽化，仿佛从未存在。',7:'Volcano Cannon of the Warlord Battle Titan 战将级战斗泰坦的火山炮',11:'火山炮开火所需的晶体，产自采矿世界煤灰十一号的一处矿脉。一群异端灵能者刺杀行星总督失败后遭到屠杀，尸体埋在熔岩河下，随后形成了这些晶体。它们会使火山炮开火时发出巨大的爆裂声；有人认为那是死去灵能者最后的惨叫。这种声音曾使在炮旁作战的人员发疯，却没有坦克或泰坦乘员受害的报道。因此，为装备火山炮的载具和泰坦提供护卫的步兵，会定期受到清洗。帝国认为，为在战场上使用如此可怕的武器，这一代价可以接受。',13:'泰坦或影剑的火山炮每发射1,500次便须更换，以免发生灾难性击发故障。',17:'掠夺者级战斗泰坦只能将火山炮安装在两处臂部挂点；战将级战斗泰坦则可在各个背甲挂点上安装。庞大的帝皇泰坦最多可在背甲上搭载六门。',20:'好战型安装于火星—阿尔法型战将级泰坦的臂部。它过于庞大、威力过强，较小的载具或泰坦无法承载，必须由战将级的等离子反应堆满足其巨大的能量需求。',23:'Estaban VII pattern 埃斯塔班七号型',25:'埃斯塔班七号型火山炮安装于“严惩号”等影剑坦克。',28:'可安装于战争使者型天罚级泰坦的背甲。',31:'这是底稿所述机械修会认可的现行型号，其运用在M35中期得到完善。',33:'帝国卫队的影剑使用22-S、Mk.IV 法厄同型火山炮。由于开火所需功率极高，影剑必须停下，断开主驱动装置，转而接通发电装置，为车内电容器充能。开火一次便会耗尽电容器中的能量，因此车辆必须继续保持静止，才能重新充能。',37:'MkII Teracharge pattern Mk.II 太级充能型',39:'据说太级充能型比后来的 Mk.IV 威力更大，却因极不稳定而从未正式服役。每次开火，它几乎都会毁掉承载它的泰坦手臂或坦克车体，最终被机械修会判定为失败设计。',42:'开火时很不稳定，危险程度几乎与失败的 Mk.II 型相当。',45:'在最初《泰坦修会》（Adeptus Titanicus）时期的游戏资料中，火山炮被称为“防御激光”。'},notes={2:'terawatt为太瓦（10的12次方瓦），原译兆瓦低了六个数量级；原文虽用energy，瓦为功率单位，译文据单位改为功率。',5:'hundred meter-tall指高一百米，不是厚一百米。',11:'被定期清洗的是护卫步兵，并非泰坦。晶体起源和影响沿所给设定，不另增解释。',17:'本段挂点描述与后面的具体型号配置存在差异，照各自原文保留，不擅自统一武器安装位置。',37:'Tera前缀对应太，原稿兆级充能型保留对照；型号中文仍为暂译。',45:'Adeptus Titanicus此处是游戏及出版时期，不是设定内的泰坦修会时代。'},terms=[('Volcano Cannon','火山炮'),('Cinderus XI','煤灰十一号'),('Belicosa Pattern','好战型'),('Castigatus','严惩号'),('Teracharge Pattern','太级充能型')])
save(1314,{2:'激光撕裂炮是帝国阿斯特赖俄斯超重型坦克使用的激光武器，通常安装在侧炮座上。',4:'Twin-linked Las-Rippers 双联激光撕裂炮'},terms=[('Las-Ripper','激光撕裂炮')],title='激光撕裂炮 Las-Ripper')
save(1315,{2:'激光毁灭炮是一种能在远距离摧毁敌方坦克的激光武器。其系统极其复杂，只有少数铸造世界还能生产，而且每一门都必须经历漫长而精细的手工制作。',3:'Rapier Laser Destroyer 细剑激光毁灭炮',5:'细剑激光毁灭炮也是一种半自动履带式武器平台的名称，帝国卫队、机械修会和星际战士都会使用。平台搭载与其同名的多管激光炮，是威力强大的反坦克武器。',7:'Rapier Laser Destroyer 细剑激光毁灭炮',10:'帝国卫队主要将这种武器用于毁灭者反坦克车。损失或损坏的激光毁灭炮极难得到补充，因此回收的坦克往往只能改装其他武器。不过，在阿玛吉多顿遭入侵期间，一批奇美拉装甲车被改装激光毁灭炮，重新定名为 APDS-6a“防御者”，成为对付欧克的有效应急措施。',12:'Heavy Laser Destroyer 重型激光毁灭炮',14:'重型激光毁灭炮是一种反装甲能力极强的重型激光武器，通常安装于处决者型反重力战车。',16:'Heavy Laser Destroyer 重型激光毁灭炮',17:'Magna Laser Destroyer 巨型激光毁灭炮',19:'荷鲁斯之乱期间，迪莫斯型维护者战车可配备巨型激光毁灭炮阵列，以撕开敌方载具的装甲。常规维护者原本用于存放破坏者炮弹药的车内空间，可改装供能电容器，大幅提高激光毁灭炮的射速。不过，过载射击要求平台保持稳定；电容器也可能使全车供能网络过载，酿成灾难。',21:'Magna Laser Destroyer 巨型激光毁灭炮'},notes={2:'原文all but a few与后半句逻辑不合，按全文仅少数铸造世界能制造的明确语境译出。',5:'同名条目兼指武器及其履带平台，避免将整个平台当成单门火炮。'},terms=[('Laser Destroyer','激光毁灭炮'),('Rapier Laser Destroyer','细剑激光毁灭炮'),('Heavy Laser Destroyer','重型激光毁灭炮'),('Magna Laser Destroyer','巨型激光毁灭炮'),('APDS-6a Defender','APDS-6a 防御者')],title='激光毁灭炮 Laser Destroyer')
save(1316,{2:'涡轮激光破坏炮是一种强大的激光能量武器，通常安装于帝国泰坦，也可用于其他超重型载具。',5:'它通常以两门或三门成组安装，以集中造成更大破坏。凭借远射程与集中的杀伤力，它最适合对付其他超重型载具。',7:'涡轮激光能严重破坏周围环境：光束可贯穿地面直达基岩，在熔融的大地上犁出长沟。在城市中，灼热光束经过时会震落屋瓦、击碎窗户，一次横扫便可夷平整排建筑。普通步兵会在瞬间燃烧、汽化；即使光束只是从头顶几米处掠过，也足以将无遮蔽士兵的血肉从骨头上烧去。主战坦克的装甲会被直接贯穿，车体被撕裂、瓦解。帝国超重型坦克也可能被一发摧毁，只是熔穿其正面装甲需要短短数秒。相比之下，即使战犬级侦察泰坦也能凭借虚空盾，承受多次涡轮激光命中。',12:'单管——部分雷鹰炮艇，以及一些“仿制”影剑，会装备单管涡轮激光破坏炮。',14:'双管——双联涡轮激光炮常安装于战犬级泰坦的臂部，有时也安装于更大的掠夺者级和战将级战斗泰坦的背甲挂点。',16:'激光爆破炮（三管）——将三根涡轮激光炮管集成在一个挂点上。掠夺者级泰坦通常在臂部装备一门或多门，部分战将级型号也如此；火星—阿尔法型战将级则常在背甲上安装一对。帝皇级泰坦也可在背甲挂点上搭载一门或多门激光爆破炮。'},terms=[('Turbo-Laser Destructor','涡轮激光破坏炮'),('Laser Blaster','激光爆破炮')])
save(1317,{2:'阿拉克纳斯重型激光炮是一种重型激光炮，有时安装于星际战士的德雷都型无畏机甲。',4:'Arachnus Heavy Lascannon 阿拉克纳斯重型激光炮'},terms=[('Arachnus Heavy Lascannon','阿拉克纳斯重型激光炮')],title='阿拉克纳斯重型激光炮 Arachnus Heavy Lascannon')
